const AVATAR_COLORS = ['#56e2cf', '#ff8b72', '#6676ea', '#a879ff', '#e8b65a', '#47a7f5', '#ec6fa8'];
const DEFAULT_HOST_URL = 'https://voiceup.shardweb.app';
const ROOM_CHANNELS = { voice: ['Geral', 'Jogando', 'Ausente'], text: ['geral', 'conversa', 'avisos'] };
const storedProfile = (() => { try { return JSON.parse(localStorage.getItem('voiceup-profile-v1') || '{}'); } catch { return {}; } })();
let myColor = AVATAR_COLORS.includes(storedProfile.color) ? storedProfile.color : AVATAR_COLORS[Math.floor(Math.random() * AVATAR_COLORS.length)];
let localStream, cameraStream, screenStream, peer, myName = storedProfile.name || '', myAvatar = storedProfile.avatar || '', micEnabled = true, remoteAudio = null, remoteMuted = false, hostedSocket = null, currentMode = 'manual', voiceContext = null, voiceAnalyser = null, voiceData = null, voiceLoopRunning = false, localSpeaking = false, latencyTimer = null, notificationsEnabled = storedProfile.notifications !== false, notificationContext = null, activeRemoteId = null, theme = storedProfile.theme || 'aurora', noiseMode = storedProfile.noiseMode || 'standard', activeVoiceChannel = ROOM_CHANNELS.voice.includes(storedProfile.voiceChannel) ? storedProfile.voiceChannel : 'Geral', activeTextChannel = ROOM_CHANNELS.text.includes(storedProfile.textChannel) ? storedProfile.textChannel : 'geral';
const hostedPeers = new Map();
const serverMembers = new Map();
const channelMessages = new Map(ROOM_CHANNELS.text.map((channel) => [channel, []]));
const unreadChannels = new Set();
const $ = (id) => document.getElementById(id);
$('theme-select').innerHTML = '<option value="aurora">Aurora · turquesa e coral</option><option value="midnight">Meia-noite · índigo e rosa</option><option value="ember">Brasa · laranja e dourado</option><option value="forest">Floresta · verde e âmbar</option><option value="snow">Neve · azul claro</option><option value="lilac">Lilás · violeta suave</option>';
$('video-frame').insertAdjacentHTML('beforeend', '<button id="fullscreen-button" type="button" title="Tela cheia" style="position:absolute;right:9px;top:9px;width:31px;height:31px;border-radius:8px;background:rgba(12,18,31,.78);color:#e8edf8;font-size:18px">⛶</button>');
$('name-input').value = myName;
$('host-url').value = storedProfile.hostUrl || DEFAULT_HOST_URL;
$('host-room').value = storedProfile.roomId || '';
$('settings-voice-channel')?.closest('div[style*="border-top"]')?.remove();
if (['360', '720', '1080'].includes(storedProfile.quality)) $('quality-select').value = storedProfile.quality;

const initials = (name) => String(name || '?').split(/\s+/).map((word) => word[0]).join('').slice(0, 2).toUpperCase();
const escapeHtml = (value) => String(value || '').replace(/[&<>'"]/g, (c) => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' }[c]));
const pack = (data) => btoa(String.fromCharCode(...new TextEncoder().encode(JSON.stringify(data))));
const unpack = (text) => JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(text.trim()), (c) => c.charCodeAt(0))));
const safeColor = (color) => AVATAR_COLORS.includes(color) ? color : '#6676ea';
const safeAvatar = (photo) => typeof photo === 'string' && photo.startsWith('data:image/') && photo.length <= 150000 ? photo : '';
const avatar = (name, color, photo = '') => { const image = safeAvatar(photo); return `<div class="avatar" style="background:${safeColor(color)}${image ? `;background-image:url('${image}');background-size:cover;background-position:center` : ''}">${image ? '' : initials(name)}</div>`; };
const audioIcon = (muted = false) => muted ? '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4zM19 9l-6 6M13 9l6 6"/></svg>' : '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4zM15.5 9.5a4 4 0 0 1 0 5M18 7a7.5 7.5 0 0 1 0 10"/></svg>';
const micIcon = (muted = false) => muted ? '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 14a3 3 0 0 0 3-3V5a3 3 0 0 0-5.2-2M5 5l14 14M6 10v1a6 6 0 0 0 9.8 4.6M12 17v4M8 21h8"/></svg>' : '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 10v1a7 7 0 0 0 14 0v-1M12 18v3M8 21h8"/></svg>';
const cameraIcon = '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="6" width="13" height="12" rx="2"/><path d="m16 10 5-3v10l-5-3z"/></svg>';
const screenIcon = '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8M12 17v4M8 10h8M15 7l3 3-3 3"/></svg>';
const bellIcon = (muted = false) => muted ? '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 9a6 6 0 0 0-9.6-4.8M5 5l14 14M6.4 8.4C6 14.8 3 15.5 3 18h13M10 21h4"/></svg>' : '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>';
function refreshMicButton() { const button = $('mic-button'); button.innerHTML = micIcon(!micEnabled); button.title = micEnabled ? 'Silenciar microfone' : 'Ativar microfone'; button.setAttribute('aria-label', button.title); }
function refreshVideoButtons() { const camera = $('cam-button'); const screen = $('screen-button'); camera.innerHTML = cameraIcon; screen.innerHTML = screenIcon; camera.title = cameraStream ? 'Desligar camera' : 'Ligar camera'; screen.title = screenStream ? 'Encerrar transmissao de tela' : 'Iniciar transmissao de tela'; camera.setAttribute('aria-label', camera.title); screen.setAttribute('aria-label', screen.title); }

function toast(message) { const t = $('toast'); t.textContent = message; t.classList.add('show'); setTimeout(() => t.classList.remove('show'), 3500); }
function refreshNotificationButton() { const button = $('notification-button'); button.innerHTML = bellIcon(!notificationsEnabled); button.title = notificationsEnabled ? 'Silenciar notificacoes sonoras' : 'Ativar notificacoes sonoras'; button.setAttribute('aria-label', button.title); button.classList.toggle('muted', !notificationsEnabled); }
function playNotification(kind) { if (!notificationsEnabled) return; try { notificationContext ||= new AudioContext(); notificationContext.resume().catch(() => {}); const patterns = { connect: [[523, 0], [784, .1]], disconnect: [[440, 0], [330, .11]], message: [[660, 0]] }; for (const [frequency, offset] of patterns[kind] || []) { const oscillator = notificationContext.createOscillator(); const gain = notificationContext.createGain(); oscillator.type = 'sine'; oscillator.frequency.value = frequency; gain.gain.setValueAtTime(.0001, notificationContext.currentTime + offset); gain.gain.exponentialRampToValueAtTime(.055, notificationContext.currentTime + offset + .012); gain.gain.exponentialRampToValueAtTime(.0001, notificationContext.currentTime + offset + .095); oscillator.connect(gain).connect(notificationContext.destination); oscillator.start(notificationContext.currentTime + offset); oscillator.stop(notificationContext.currentTime + offset + .11); } } catch { /* optional sound */ } }
function setStatus(label, connected = false) { const s = $('call-status'); s.classList.toggle('connected', connected); s.lastChild.textContent = ` ${label}`; }
function addMessage(text, author, mine = false, color = mine ? myColor : peer?.color) { const m = document.createElement('div'); m.className = `message${mine ? ' mine' : ''}`; m.innerHTML = `<div class="author" style="color:${safeColor(color)}">${escapeHtml(author)}</div>${escapeHtml(text)}`; $('messages').append(m); $('messages').scrollTop = $('messages').scrollHeight; }
function saveProfile() { localStorage.setItem('voiceup-profile-v1', JSON.stringify({ name: $('name-input')?.value.trim() || myName, avatar: myAvatar, color: myColor, hostUrl: $('host-url')?.value.trim() || DEFAULT_HOST_URL, roomId: $('host-room')?.value.trim() || '', voiceChannel: activeVoiceChannel, textChannel: activeTextChannel, quality: $('quality-select')?.value || '720', notifications: notificationsEnabled, theme, noiseMode, lastMode: currentMode })); }
function channelAvatar(member) { const photo = safeAvatar(member.avatar); const initialsText = initials(member.name); return `<span class="channel-avatar" title="${escapeHtml(member.name)}" style="background:${safeColor(member.color)}${photo ? `;background-image:url('${photo}');background-size:cover;background-position:center` : ''}">${photo ? '' : initialsText}</span>`; }
function rememberHostedMember(member, voiceChannel = activeVoiceChannel) { if (!member?.id) return; serverMembers.set(member.id, { ...member, voiceChannel: ROOM_CHANNELS.voice.includes(member.voiceChannel) ? member.voiceChannel : voiceChannel }); }
function rememberCurrentMember() { if (!hostedSocket?.id) return; rememberHostedMember({ id: hostedSocket.id, name: myName, color: myColor, avatar: myAvatar, voiceChannel: activeVoiceChannel }); }
function renderChannelMessages() { const messages = channelMessages.get(activeTextChannel) || []; $('messages').innerHTML = messages.length ? '' : `<div class="system-message">Nenhuma mensagem em #${escapeHtml(activeTextChannel)} ainda.</div>`; messages.forEach((message) => addMessage(message.text, message.name, message.mine, message.color)); }
function selectTextChannel(channel) { if (!ROOM_CHANNELS.text.includes(channel)) return; activeTextChannel = channel; unreadChannels.delete(channel); renderRoomChannels(); renderChannelMessages(); saveProfile(); }
function receiveHostedText({ from, text, textChannel, name, color }) { const channel = ROOM_CHANNELS.text.includes(textChannel) ? textChannel : 'geral'; const message = { text, name, color, mine: from === hostedSocket?.id }; channelMessages.get(channel).push(message); if (channel === activeTextChannel) { addMessage(message.text, message.name, message.mine, message.color); if (!message.mine) playNotification('message'); } else if (!message.mine) { unreadChannels.add(channel); playNotification('message'); } renderRoomChannels(); }
function renderRoomChannels() { const panel = $('room-channels'); const members = [...serverMembers.values()]; panel.innerHTML = `<h3>CANAIS DE VOZ</h3>${ROOM_CHANNELS.voice.map((channel) => { const people = members.filter((member) => member.voiceChannel === channel); return `<button class="room-channel voice-channel${channel === activeVoiceChannel ? ' active' : ''}" data-voice-channel="${channel}"><span>🔊 ${channel}</span><span class="channel-avatars">${people.slice(0, 4).map(channelAvatar).join('')}${people.length > 4 ? `<i>+${people.length - 4}</i>` : ''}</span></button>`; }).join('')}<h3>CANAIS DE TEXTO</h3>${ROOM_CHANNELS.text.map((channel) => `<button class="room-channel${channel === activeTextChannel ? ' active' : ''}" data-text-channel="${channel}"><span># ${channel}</span>${unreadChannels.has(channel) ? '<b class="unread-dot" title="Nova mensagem"></b>' : ''}</button>`).join('')}`; $('message-input').placeholder = `Mensagem em #${activeTextChannel}`; panel.querySelectorAll('[data-voice-channel]').forEach((button) => button.addEventListener('click', () => switchVoiceChannel(button.dataset.voiceChannel))); panel.querySelectorAll('[data-text-channel]').forEach((button) => button.addEventListener('click', () => selectTextChannel(button.dataset.textChannel))); }
function paintAvatar(target, name, color, photo = '') { const image = safeAvatar(photo); target.textContent = image ? '' : initials(name); target.style.background = safeColor(color); target.style.backgroundImage = image ? `url('${image}')` : ''; target.style.backgroundSize = image ? 'cover' : ''; target.style.backgroundPosition = image ? 'center' : ''; }
function selfParticipant() { return `${avatar(myName, myColor, myAvatar)}<div><strong>${escapeHtml(myName)}</strong><small>Voce <span id="self-ping" style="margin-left:4px;color:#8995ab">• Ping —</span></small></div>`; }
function updatePingBadge(value) { const badge = $('self-ping'); if (!badge) return; const ping = Number(value); if (!Number.isFinite(ping) || ping < 0) { badge.textContent = '• Ping —'; badge.style.color = '#8995ab'; return; } badge.textContent = `• Ping ${Math.round(ping)} ms`; badge.style.color = ping <= 80 ? '#56e2cf' : ping <= 180 ? '#e8b65a' : '#ff8b72'; }
function applyMyColor(color) { if (!AVATAR_COLORS.includes(color) || color === myColor) return; myColor = color; saveProfile(); if (currentMode === 'hosted') renderHostedParticipants(); else { const own = $('self-participant'); if (own) own.innerHTML = selfParticipant(); } paintAvatar($('self-avatar'), myName, myColor, myAvatar); if (!peer?.name && !activeRemoteId) paintAvatar($('stage-avatar'), myName, myColor, myAvatar); }
function readProfilePhoto(file) { if (!file) return; if (file.size > 5 * 1024 * 1024) return toast('Escolha uma imagem de ate 5 MB.'); const reader = new FileReader(); reader.onload = () => { const source = new Image(); source.onload = () => { const canvas = document.createElement('canvas'); const size = 160; canvas.width = size; canvas.height = size; const scale = Math.max(size / source.width, size / source.height); canvas.getContext('2d').drawImage(source, (size - source.width * scale) / 2, (size - source.height * scale) / 2, source.width * scale, source.height * scale); myAvatar = canvas.toDataURL('image/jpeg', .82); saveProfile(); if (!$('app').classList.contains('hidden')) { paintAvatar($('self-avatar'), myName, myColor, myAvatar); if (currentMode === 'hosted') renderHostedParticipants(); } toast('Foto de perfil salva. Ela sera enviada ao entrar na chamada.'); }; source.src = reader.result; }; reader.readAsDataURL(file); }
function applyTheme(nextTheme) { theme = ['aurora', 'midnight', 'ember', 'forest', 'snow', 'lilac'].includes(nextTheme) ? nextTheme : 'aurora'; document.body.classList.remove('theme-midnight', 'theme-ember', 'theme-forest', 'theme-snow', 'theme-lilac'); if (theme !== 'aurora') document.body.classList.add(`theme-${theme}`); }

function showPeer(name, state = 'Pareando...', connected = false, color = peer?.color) { if (!name) return; let row = $('peer-other'); if (!row) { row = document.createElement('div'); row.id = 'peer-other'; row.className = 'participant'; $('participants').append(row); } row.innerHTML = `${avatar(name, color, peer?.avatar)}<div style="min-width:0;flex:1"><strong>${escapeHtml(name)}</strong><small>${state}</small></div><button id="peer-mute-button" class="participant-mute${remoteMuted ? ' muted' : ''}" type="button" title="Silenciar somente para voce" aria-label="Silenciar somente para voce" style="width:32px;height:32px;border-radius:8px;background:#29354b;color:#dbe5f4">${audioIcon(remoteMuted)}</button>`; $('peer-mute-button').addEventListener('click', togglePeerMute); $('count').textContent = '2'; paintAvatar($('stage-avatar'), name, color, peer?.avatar); if (connected) { $('stage-name').textContent = `${name} esta na conversa`; $('stage-message').textContent = 'Conexao direta estabelecida. Fale a vontade.'; } else { $('stage-name').textContent = `Conectando com ${name}`; $('stage-message').textContent = 'Aguardando a conexao P2P terminar...'; } }
function togglePeerMute() { remoteMuted = !remoteMuted; if (remoteAudio) remoteAudio.muted = remoteMuted; showPeer(peer?.name, remoteMuted ? 'Conectado · audio silenciado' : 'Conectado', true, peer?.color); }

function hostedRow(p) { return `<div class="participant${p.speaking ? ' speaking' : ''}" data-hosted-peer="${escapeHtml(p.id)}">${avatar(p.name, p.color, p.avatar)}<div style="min-width:0;flex:1"><strong>${escapeHtml(p.name)}</strong><small>${p.connected ? 'Conectado · P2P' : 'Conectando...'}</small></div><button class="hosted-mute" data-peer-id="${escapeHtml(p.id)}" type="button" title="Silenciar somente para voce" aria-label="Silenciar somente para voce" style="width:32px;height:32px;border-radius:8px;background:${p.muted ? '#533e52' : '#29354b'};color:${p.muted ? '#ffb0bd' : '#dbe5f4'}">${audioIcon(p.muted)}</button></div>`; }
function renderHostedParticipants() { $('participants').innerHTML = `<div id="self-participant" class="participant">${selfParticipant()}</div>${[...hostedPeers.values()].map(hostedRow).join('')}`; $('count').textContent = String(hostedPeers.size + 1); document.querySelectorAll('.hosted-mute').forEach((button) => button.addEventListener('click', () => toggleHostedMute(button.dataset.peerId))); }
function toggleHostedMute(id) { const p = hostedPeers.get(id); if (!p) return; p.muted = !p.muted; if (p.audio) p.audio.muted = p.muted; renderHostedParticipants(); toast(p.muted ? `Audio de ${p.name} silenciado.` : `Audio de ${p.name} reativado.`); }
function showHostedStage(p, connected = false) { if (!p) return; activeRemoteId ||= p.id; if (activeRemoteId !== p.id) return; paintAvatar($('stage-avatar'), p.name, p.color, p.avatar); $('stage-name').textContent = connected ? `${p.name} esta na conversa` : `Conectando com ${p.name}`; $('stage-message').textContent = connected ? `${hostedPeers.size} participante(s) conectado(s) por P2P.` : 'Aguardando a conexao P2P terminar...'; }

function startVoiceDetection() { if (!localStream || voiceLoopRunning) return; try { voiceContext = new AudioContext(); voiceContext.resume().catch(() => {}); voiceAnalyser = voiceContext.createAnalyser(); voiceAnalyser.fftSize = 512; voiceData = new Uint8Array(voiceAnalyser.fftSize); voiceContext.createMediaStreamSource(localStream).connect(voiceAnalyser); voiceLoopRunning = true; const sample = () => { voiceAnalyser.getByteTimeDomainData(voiceData); let sum = 0; for (const value of voiceData) sum += Math.abs(value - 128); const speaking = micEnabled && sum / voiceData.length > 5; if (speaking !== localSpeaking) { localSpeaking = speaking; $('self-participant')?.classList.toggle('speaking', speaking); sendSignal('voice-state', speaking); } requestAnimationFrame(sample); }; sample(); } catch { /* indicator optional */ } }
async function requestAudio() { try { const noiseEnabled = noiseMode !== 'off'; localStream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: noiseEnabled, noiseSuppression: noiseEnabled, autoGainControl: noiseMode === 'strong' }, video: false }); $('connection-state').textContent = noiseMode === 'strong' ? 'Microfone · reducao forte' : noiseEnabled ? 'Microfone ativo' : 'Microfone sem supressao'; startVoiceDetection(); } catch { $('connection-state').textContent = 'Sem acesso ao microfone'; toast('Libere o microfone para falar.'); } }
function setCallMode(mode) { currentMode = mode; const hosted = mode === 'hosted'; document.querySelector('.room-name span:last-child').textContent = hosted ? 'Sala P2P via servidor host' : 'Conexao direta manual'; document.querySelector('.content header h2').textContent = hosted ? 'Sala P2P em grupo' : 'P2P sem servidor host'; $('room-channels').classList.toggle('hidden', !hosted); if (hosted) renderRoomChannels(); }
function waitForIce(pc) { return new Promise((resolve) => { if (pc.iceGatheringState === 'complete') return resolve(true); let done = false; let settleTimer; const finish = (complete) => { if (done) return; done = true; clearTimeout(timeout); clearTimeout(settleTimer); pc.removeEventListener('icegatheringstatechange', check); pc.removeEventListener('icecandidate', candidateArrived); resolve(complete); }; const check = () => { if (pc.iceGatheringState === 'complete') finish(true); }; const candidateArrived = ({ candidate }) => { if (!candidate) return; clearTimeout(settleTimer); settleTimer = setTimeout(() => finish(false), 900); }; const timeout = setTimeout(() => finish(false), 5000); pc.addEventListener('icegatheringstatechange', check); pc.addEventListener('icecandidate', candidateArrived); }); }
function readyHostedPeers() { return [...hostedPeers.values()].filter((p) => p.channel?.readyState === 'open'); }
function sendSignal(type, description) { if (currentMode === 'hosted') readyHostedPeers().forEach((p) => p.channel.send(JSON.stringify({ type, description }))); else if (peer?.channel?.readyState === 'open') peer.channel.send(JSON.stringify({ type, description })); }
function hasActiveCall() { return currentMode === 'hosted' ? readyHostedPeers().length > 0 : peer?.channel?.readyState === 'open'; }
function startPingMeasure() { clearInterval(latencyTimer); const sample = async () => { if (currentMode === 'hosted' && hostedSocket?.connected) hostedSocket.emit('latency-ping', { sentAt: Date.now() }); else if (peer?.pc?.connectionState === 'connected') { const stats = await peer.pc.getStats(); stats.forEach((report) => { if (report.type === 'candidate-pair' && report.state === 'succeeded' && Number.isFinite(report.currentRoundTripTime)) updatePingBadge(report.currentRoundTripTime * 1000); }); } }; sample(); latencyTimer = setInterval(sample, 2000); }

function bindChannel(channel) { peer.channel = channel; channel.onmessage = ({ data }) => receiveData(data); channel.onopen = () => { channel.send(JSON.stringify({ type: 'intro', name: myName, color: myColor, avatar: myAvatar })); markConnected(); }; channel.onclose = () => { if (peer?.pc.connectionState !== 'closed') setStatus('Canal P2P fechado'); }; }
function displayRemoteVideo(stream, label) { if (!stream) return false; $('remote-video').srcObject = stream; $('remote-video').play().catch(() => {}); if (label) document.querySelector('.video-label').textContent = label; $('video-frame').classList.remove('hidden'); $('identity-stage').classList.add('hidden'); return true; }
function showManualVideo(label = 'Video recebido') { if (!peer) return; peer.videoLabel = label; displayRemoteVideo(peer.videoStream, label); }
function showHostedVideo(p, label = 'Video recebido') { if (!p) return; p.videoLabel = label; activeRemoteId = p.id; displayRemoteVideo(p.videoStream, label); }
function makePeer() { const pc = new RTCPeerConnection({ iceServers: [{ urls: 'stun:stun.l.google.com:19302' }, { urls: 'stun:stun.cloudflare.com:3478' }], iceCandidatePoolSize: 2 }); peer = { pc, channel: null, name: '', color: '', makingOffer: false, manualCandidates: [], videoStream: null, videoLabel: 'Video recebido' }; localStream?.getTracks().forEach((track) => pc.addTrack(track, localStream)); pc.addTransceiver('video', { direction: 'sendrecv' }); pc.ontrack = ({ track, streams }) => { const stream = streams[0] || new MediaStream([track]); if (track.kind === 'audio') { remoteAudio?.pause(); remoteAudio = new Audio(); remoteAudio.srcObject = stream; remoteAudio.autoplay = true; remoteAudio.muted = remoteMuted; remoteAudio.play().catch(() => {}); } if (track.kind === 'video') { peer.videoStream = stream; const reveal = () => showManualVideo(peer.videoLabel); track.onunmute = reveal; if (track.readyState === 'live' && !track.muted) reveal(); } }; pc.ondatachannel = ({ channel }) => bindChannel(channel); pc.onicecandidate = ({ candidate }) => { if (candidate && !peer.remoteId) peer.manualCandidates.push(candidate.toJSON()); }; pc.onconnectionstatechange = () => { if (pc.connectionState === 'connecting') setStatus('Conectando P2P...'); if (pc.connectionState === 'connected' && peer.channel?.readyState === 'open') markConnected(); if (['failed', 'disconnected'].includes(pc.connectionState)) { if (pc.connectionState === 'disconnected') playNotification('disconnect'); setStatus('Nao foi possivel conectar'); if (peer?.name) showPeer(peer.name, 'Falha na conexao', false, peer.color); } }; pc.onnegotiationneeded = async () => { if (!peer?.channel || peer.channel.readyState !== 'open' || peer.makingOffer) return; try { peer.makingOffer = true; await pc.setLocalDescription(await pc.createOffer()); sendSignal('signal-offer', pc.localDescription); } finally { peer.makingOffer = false; } }; return pc; }
function markConnected() { if (!peer?.name) return; showPeer(peer.name, 'Conectado · P2P direto', true, peer.color); setStatus('Conexao P2P direta ativa', true); $('pair-panel').classList.add('hidden'); startPingMeasure(); if (!peer.connectSoundPlayed) { peer.connectSoundPlayed = true; playNotification('connect'); } }
async function receiveData(raw) { try { const msg = JSON.parse(raw); if (msg.type === 'chat') { playNotification('message'); return addMessage(msg.text, msg.name, false, msg.color || peer?.color); } if (msg.type === 'intro') { peer.name = msg.name; peer.color = msg.color || peer.color; peer.avatar = msg.avatar || peer.avatar; return markConnected(); } if (msg.type === 'video-on') { showManualVideo(msg.description === 'screen' ? 'Tela compartilhada' : 'Video recebido'); return; } if (msg.type === 'video-off') { $('remote-video').srcObject = null; $('video-frame').classList.add('hidden'); $('identity-stage').classList.remove('hidden'); return; } if (msg.type === 'voice-state') return $('peer-other')?.classList.toggle('speaking', Boolean(msg.description)); if (msg.type === 'signal-offer') { await peer.pc.setRemoteDescription(msg.description); await peer.pc.setLocalDescription(await peer.pc.createAnswer()); return sendSignal('signal-answer', peer.pc.localDescription); } if (msg.type === 'signal-answer') await peer.pc.setRemoteDescription(msg.description); } catch { toast('Erro ao atualizar a conexao direta.'); } }
async function addManualCandidates(candidates) { for (const candidate of candidates || []) { try { await peer.pc.addIceCandidate(candidate); } catch { /* candidate may already be in SDP */ } } }

function videoSenders() { if (currentMode === 'hosted') return readyHostedPeers().map((p) => p.pc?.getTransceivers().find((t) => t.receiver.track.kind === 'video')?.sender).filter(Boolean); return [peer?.pc?.getTransceivers().find((t) => t.receiver.track.kind === 'video')?.sender].filter(Boolean); }
function quality() { const h = Number($('quality-select').value); return { width: { ideal: h * 16 / 9 }, height: { ideal: h }, frameRate: { ideal: h >= 1080 ? 30 : 24, max: 30 } }; }
async function publishVideo(track, kind) { const senders = videoSenders(); if (!senders.length) throw new Error('Canal de video indisponivel.'); const results = await Promise.allSettled(senders.map((sender) => sender.replaceTrack(track))); if (!results.some((result) => result.status === 'fulfilled')) throw new Error('Nenhum participante estava pronto para receber video.'); sendSignal('video-on', kind); }
async function startCamera() { if (!hasActiveCall()) return toast('Finalize o pareamento antes de ligar a camera.'); try { screenStream?.getTracks().forEach((t) => { t.onended = null; t.stop(); }); screenStream = null; cameraStream?.getTracks().forEach((t) => t.stop()); cameraStream = await navigator.mediaDevices.getUserMedia({ video: quality(), audio: false }); $('local-video').srcObject = cameraStream; $('local-video').classList.add('visible'); await publishVideo(cameraStream.getVideoTracks()[0], 'camera'); $('cam-button').classList.add('on'); $('screen-button').classList.remove('share-on'); refreshVideoButtons(); } catch { cameraStream?.getTracks().forEach((t) => t.stop()); cameraStream = null; toast('Nao foi possivel acessar a camera.'); refreshVideoButtons(); } }
async function stopVideo() { await Promise.allSettled(videoSenders().map((sender) => sender.replaceTrack(null))); cameraStream?.getTracks().forEach((t) => t.stop()); screenStream?.getTracks().forEach((t) => t.stop()); cameraStream = null; screenStream = null; $('local-video').srcObject = null; $('local-video').classList.remove('visible'); $('cam-button').classList.remove('on'); $('screen-button').classList.remove('share-on'); refreshVideoButtons(); sendSignal('video-off'); }
async function shareScreen() { if (!hasActiveCall()) return toast('Finalize o pareamento antes de compartilhar a tela.'); try { screenStream?.getTracks().forEach((t) => { t.onended = null; t.stop(); }); screenStream = await navigator.mediaDevices.getDisplayMedia({ video: { frameRate: { ideal: 30, max: 30 } }, audio: false }); const track = screenStream.getVideoTracks()[0]; track.onended = () => stopVideo(); $('local-video').srcObject = screenStream; $('local-video').classList.add('visible'); await publishVideo(track, 'screen'); $('screen-button').classList.add('share-on'); $('cam-button').classList.remove('on'); refreshVideoButtons(); } catch (error) { screenStream?.getTracks().forEach((t) => t.stop()); screenStream = null; $('local-video').srcObject = null; $('local-video').classList.remove('visible'); refreshVideoButtons(); if (error.name !== 'NotAllowedError') toast(error.message || 'Nao foi possivel compartilhar a tela.'); } }

function bindHostedChannel(p, channel) { p.channel = channel; channel.onmessage = ({ data }) => receiveHostedData(p, data); channel.onopen = () => { channel.send(JSON.stringify({ type: 'intro', name: myName, color: myColor, avatar: myAvatar })); markHostedConnected(p); }; channel.onclose = () => { if (!p.left) { p.connected = false; renderHostedParticipants(); } }; }
function markHostedConnected(p) { p.connected = true; renderHostedParticipants(); showHostedStage(p, true); setStatus(`${readyHostedPeers().length + 1} pessoas conectadas · P2P`, true); $('pair-panel').classList.add('hidden'); startPingMeasure(); if (!p.connectSoundPlayed) { p.connectSoundPlayed = true; playNotification('connect'); } }
function attachHostedTrack(p, track, streams) { const stream = streams[0] || new MediaStream([track]); if (track.kind === 'audio') { p.audio?.pause(); p.audio = new Audio(); p.audio.srcObject = stream; p.audio.autoplay = true; p.audio.muted = p.muted; p.audio.play().catch(() => {}); } if (track.kind === 'video') { p.videoStream = stream; const reveal = () => showHostedVideo(p, p.videoLabel || 'Video recebido'); track.onunmute = reveal; if (track.readyState === 'live' && !track.muted) reveal(); } }
function makeHostedConnection(p) { const pc = new RTCPeerConnection({ iceServers: [{ urls: 'stun:stun.l.google.com:19302' }, { urls: 'stun:stun.cloudflare.com:3478' }], iceCandidatePoolSize: 2 }); p.pc = pc; localStream?.getTracks().forEach((track) => pc.addTrack(track, localStream)); const videoTransceiver = pc.addTransceiver('video', { direction: 'sendrecv' }); const activeVideoTrack = (screenStream || cameraStream)?.getVideoTracks?.()[0]; if (activeVideoTrack) videoTransceiver.sender.replaceTrack(activeVideoTrack).catch(() => {}); pc.ontrack = ({ track, streams }) => attachHostedTrack(p, track, streams); pc.ondatachannel = ({ channel }) => bindHostedChannel(p, channel); pc.onicecandidate = ({ candidate }) => { if (candidate) hostedSocket?.emit('signal', { target: p.id, data: { candidate: candidate.toJSON() } }); }; pc.onconnectionstatechange = () => { if (pc.connectionState === 'connected' && p.channel?.readyState === 'open') markHostedConnected(p); if (['failed', 'disconnected', 'closed'].includes(pc.connectionState) && !p.left && pc.connectionState !== 'closed') { p.connected = false; renderHostedParticipants(); } }; return pc; }
async function createHostedPeer(id, name, initiator, color, avatarPhoto = '') { if (hostedPeers.has(id)) return hostedPeers.get(id); const p = { id, name: name || 'Visitante', color: safeColor(color), avatar: safeAvatar(avatarPhoto), channel: null, pc: null, pendingCandidates: [], connected: false, muted: false, speaking: false, left: false, videoStream: null, videoLabel: 'Video recebido' }; hostedPeers.set(id, p); makeHostedConnection(p); renderHostedParticipants(); showHostedStage(p, false); if (initiator) { bindHostedChannel(p, p.pc.createDataChannel('voiceup-chat')); await p.pc.setLocalDescription(await p.pc.createOffer()); hostedSocket.emit('signal', { target: id, data: { description: p.pc.localDescription } }); } return p; }
async function receiveHostedSignal({ from, name, color, avatar, data }) { try { const p = hostedPeers.get(from) || await createHostedPeer(from, name, false, color, avatar); if (data.description) { await p.pc.setRemoteDescription(data.description); if (p.pendingCandidates.length) await Promise.all(p.pendingCandidates.splice(0).map((candidate) => p.pc.addIceCandidate(candidate))); if (data.description.type === 'offer') { await p.pc.setLocalDescription(await p.pc.createAnswer()); hostedSocket.emit('signal', { target: from, data: { description: p.pc.localDescription } }); } } if (data.candidate) { if (p.pc.remoteDescription) await p.pc.addIceCandidate(data.candidate); else p.pendingCandidates.push(data.candidate); } } catch { toast('Erro ao negociar uma conexao da sala.'); } }
async function receiveHostedData(p, raw) { try { const msg = JSON.parse(raw); if (msg.type === 'chat') { playNotification('message'); return addMessage(msg.text, msg.name || p.name, false, msg.color || p.color); } if (msg.type === 'intro') { p.name = msg.name || p.name; p.color = safeColor(msg.color || p.color); p.avatar = safeAvatar(msg.avatar || p.avatar); return markHostedConnected(p); } if (msg.type === 'video-on') { showHostedVideo(p, msg.description === 'screen' ? 'Tela compartilhada' : 'Video recebido'); return; } if (msg.type === 'video-off' && activeRemoteId === p.id) { $('remote-video').srcObject = null; $('video-frame').classList.add('hidden'); $('identity-stage').classList.remove('hidden'); return; } if (msg.type === 'voice-state') { p.speaking = Boolean(msg.description); renderHostedParticipants(); } } catch { toast('Erro ao receber dados de um participante.'); } }

async function enterApp(mode = 'manual') { $('welcome').classList.add('hidden'); $('app').classList.remove('hidden'); setCallMode(mode); $('self-name').textContent = myName; paintAvatar($('self-avatar'), myName, myColor, myAvatar); paintAvatar($('stage-avatar'), myName, myColor, myAvatar); $('stage-name').textContent = 'Voce esta pronto'; $('participants').innerHTML = `<div id="self-participant" class="participant">${selfParticipant()}</div>`; await requestAudio(); }
async function makeOffer() { await enterApp('manual'); const pc = makePeer(); bindChannel(pc.createDataChannel('voiceup-chat')); setStatus('Coletando rotas P2P...'); await pc.setLocalDescription(await pc.createOffer()); const complete = await waitForIce(pc); $('pair-instruction').textContent = complete ? '1. Copie este convite e envie para a outra pessoa.' : '1. Convite preparado com as rotas disponiveis. Copie e envie para a outra pessoa.'; $('pair-code').value = pack({ type: 'offer', name: myName, color: myColor, avatar: myAvatar, description: pc.localDescription, candidates: peer.manualCandidates }); }
async function acceptOffer() { try { const data = unpack($('offer-input').value); if (data.type !== 'offer') throw new Error(); if (data.color === myColor) applyMyColor(AVATAR_COLORS.find((color) => color !== data.color)); await enterApp('manual'); const pc = makePeer(); peer.name = data.name; peer.color = data.color; peer.avatar = data.avatar; showPeer(data.name, 'Preparando resposta...', false, data.color); await pc.setRemoteDescription(data.description); await addManualCandidates(data.candidates); await pc.setLocalDescription(await pc.createAnswer()); await waitForIce(pc); $('pair-instruction').textContent = '1. Copie esta resposta e envie de volta para quem criou o convite.'; $('pair-code').value = pack({ type: 'answer', name: myName, color: myColor, avatar: myAvatar, description: pc.localDescription, candidates: peer.manualCandidates }); $('pair-panel').classList.add('answer-only'); } catch { toast('Convite invalido. Peca um novo codigo.'); } }
function loadSocketClient(hostUrl) { return new Promise((resolve, reject) => { if (window.io) return resolve(window.io); const script = document.createElement('script'); script.src = `${hostUrl.replace(/\/$/, '')}/socket.io/socket.io.js`; script.onload = () => window.io ? resolve(window.io) : reject(new Error('socket.io nao encontrado')); script.onerror = () => reject(new Error('nao foi possivel acessar o servidor host')); document.head.append(script); }); }
function decodeHostCode(value) { if (!value.startsWith('VU1:')) return value; try { const { host } = JSON.parse(atob(value.slice(4))); return typeof host === 'string' ? host : value; } catch { return value; } }
function removeHostedPeer(id, name) { const p = hostedPeers.get(id); if (p) { p.left = true; p.audio?.pause(); p.pc?.close(); hostedPeers.delete(id); } if (activeRemoteId === id) activeRemoteId = hostedPeers.keys().next().value || null; renderHostedParticipants(); if (activeRemoteId) showHostedStage(hostedPeers.get(activeRemoteId), true); else { paintAvatar($('stage-avatar'), myName, myColor, myAvatar); $('stage-name').textContent = 'Voce esta pronto'; $('stage-message').textContent = `${name || 'A outra pessoa'} saiu da chamada.`; } setStatus(hostedPeers.size ? `${hostedPeers.size + 1} pessoas na sala` : 'Aguardando participante', hostedPeers.size > 0); playNotification('disconnect'); }
function clearHostedVoice() { hostedPeers.forEach((p) => { p.left = true; p.audio?.pause(); p.pc?.close(); }); hostedPeers.clear(); activeRemoteId = null; renderHostedParticipants(); }
function switchVoiceChannel(channel) { const next = ROOM_CHANNELS.voice.includes(channel) ? channel : 'Geral'; if (!hostedSocket?.connected || currentMode !== 'hosted') return; if (next === activeVoiceChannel) return; clearHostedVoice(); activeVoiceChannel = next; rememberCurrentMember(); renderRoomChannels(); saveProfile(); hostedSocket.emit('switch-voice-channel', { voiceChannel: next }); setStatus(`Entrando no canal de voz ${next}...`); }
async function joinHostedRoom() { const hostUrl = decodeHostCode($('host-url').value.trim()).replace(/\/$/, ''); const roomId = $('host-room').value.trim(); const voiceChannel = $('voice-channel').value.trim() || 'Geral'; if (!myName) return toast('Informe seu nome antes de entrar.'); if (!/^https?:\/\//i.test(hostUrl)) return toast('Use o endereco completo ou o codigo mostrado pelo servidor host.'); if (!roomId) return toast('Informe um codigo de sala.'); try { await enterApp('hosted'); $('pair-panel').classList.add('hidden'); setStatus('Conectando ao servidor host...'); const ioFactory = await loadSocketClient(hostUrl); hostedSocket = ioFactory(hostUrl, { transports: ['websocket', 'polling'], timeout: 10000 }); hostedSocket.on('connect', () => hostedSocket.emit('join-room', { roomId, voiceChannel, name: myName, color: myColor, avatar: myAvatar })); hostedSocket.on('color-assigned', ({ color }) => applyMyColor(color)); hostedSocket.on('room-joined', ({ peers, voiceChannel: joinedChannel }) => { if (joinedChannel) $('voice-channel').value = joinedChannel; const occupied = new Set(peers.map((p) => p.color)); if (occupied.has(myColor)) applyMyColor(AVATAR_COLORS.find((color) => !occupied.has(color)) || myColor); peers.forEach((p) => createHostedPeer(p.id, p.name, true, p.color, p.avatar)); }); hostedSocket.on('peer-joined', ({ id, name, color, avatar }) => createHostedPeer(id, name, false, color, avatar)); hostedSocket.on('text-message', ({ from, text, textChannel, name, color }) => { if ((textChannel || 'geral').toLowerCase() !== ($('text-channel').value.trim() || 'geral').toLowerCase()) return; const mine = from === hostedSocket.id; if (!mine) playNotification('message'); addMessage(text, name, mine, color); }); hostedSocket.on('latency-pong', ({ sentAt }) => { const ping = Date.now() - Number(sentAt); if (Number.isFinite(ping) && ping >= 0 && ping < 10000) updatePingBadge(ping); }); hostedSocket.on('signal', receiveHostedSignal); hostedSocket.on('peer-left', ({ id, name }) => removeHostedPeer(id, name)); hostedSocket.on('app-error', (message) => toast(message)); hostedSocket.on('connect_error', () => { setStatus('Servidor host indisponivel'); toast('Nao foi possivel acessar esse servidor host.'); }); } catch (error) { toast(error.message || 'Nao foi possivel iniciar a conexao hospedada.'); } }

async function joinHostedRoom() {
  const hostUrl = decodeHostCode($('host-url').value.trim()).replace(/\/$/, '');
  const roomId = $('host-room').value.trim();
  if (!myName) return toast('Informe seu nome antes de entrar.');
  if (!/^https?:\/\//i.test(hostUrl)) return toast('Use o endereco completo ou o codigo mostrado pelo servidor host.');
  if (!roomId) return toast('Informe um codigo de sala.');
  try {
    await enterApp('hosted');
    $('pair-panel').classList.add('hidden');
    setStatus('Conectando ao servidor host...');
    const ioFactory = await loadSocketClient(hostUrl);
    hostedSocket = ioFactory(hostUrl, { transports: ['websocket', 'polling'], timeout: 10000 });
    hostedSocket.on('connect', () => { rememberCurrentMember(); renderRoomChannels(); hostedSocket.emit('join-room', { roomId, voiceChannel: activeVoiceChannel, name: myName, color: myColor, avatar: myAvatar }); });
    hostedSocket.on('color-assigned', ({ color }) => applyMyColor(color));
    hostedSocket.on('room-presence', ({ members }) => { serverMembers.clear(); rememberCurrentMember(); (members || []).forEach((member) => rememberHostedMember(member)); renderRoomChannels(); });
    hostedSocket.on('room-joined', ({ peers, voiceChannel }) => {
      if (ROOM_CHANNELS.voice.includes(voiceChannel)) activeVoiceChannel = voiceChannel;
      rememberCurrentMember();
      (peers || []).forEach((peer) => rememberHostedMember(peer, activeVoiceChannel));
      renderRoomChannels();
      const occupied = new Set(peers.map((p) => p.color));
      if (occupied.has(myColor)) applyMyColor(AVATAR_COLORS.find((color) => !occupied.has(color)) || myColor);
      peers.forEach((p) => createHostedPeer(p.id, p.name, true, p.color, p.avatar));
    });
    hostedSocket.on('peer-joined', ({ id, name, color, avatar }) => { rememberHostedMember({ id, name, color, avatar }, activeVoiceChannel); renderRoomChannels(); createHostedPeer(id, name, false, color, avatar); });
    hostedSocket.on('text-message', receiveHostedText);
    hostedSocket.on('latency-pong', ({ sentAt }) => { const ping = Date.now() - Number(sentAt); if (Number.isFinite(ping) && ping >= 0 && ping < 10000) updatePingBadge(ping); });
    hostedSocket.on('signal', receiveHostedSignal);
    hostedSocket.on('peer-left', ({ id, name }) => removeHostedPeer(id, name));
    hostedSocket.on('app-error', (message) => toast(message));
    hostedSocket.on('connect_error', () => { setStatus('Servidor host indisponivel'); toast('Nao foi possivel acessar esse servidor host.'); });
  } catch (error) { toast(error.message || 'Nao foi possivel iniciar a conexao hospedada.'); }
}

